parameters.jsCode:
// 🧠 UX ENGINE: UPSELL & AI GENERATOR
const triggerData = $('TA Engine Trigger').first().json;

// 1. Get Current Selections
let requested = triggerData.request_types || [];

// Safety: Handle string input
if (typeof requested === 'string') {
  requested = requested.replace(/[\[\]"']/g, '').split(',').map(s => s.trim());
}

// Normalize to Uppercase
const selectedSet = new Set(requested.map(r => r.toUpperCase()));

// 2. Define All Services
const allServices = [
  { id: 'MOMENTUM', text: '🚀 Momentum' },
  { id: 'TREND', text: '📈 Trend' },
  { id: 'VOLATILITY', text: '⚡ Volatility' },
  { id: 'CHARTS', text: '🖼️ Charts' }
];

// 3. Identify Missing Services
const missingOptions = allServices.filter(service => !selectedSet.has(service.id));

// 4. Build Buttons
const buttons = [];

// A. Add "Missing Service" Buttons
if (missingOptions.length > 0) {
  missingOptions.forEach(opt => {
    buttons.push([ { text: `Add ${opt.text}`, callback_data: opt.id } ]);
  });
}

// B. Add "AI Summary" Button (Conditional Logic)
// Condition: Show ONLY if at least one text indicator is present
const hasIndicators = selectedSet.has('MOMENTUM') || selectedSet.has('TREND') || selectedSet.has('VOLATILITY');

if (hasIndicators) {
  // Note: We use a short ID because Telegram limits callback data to 64 bytes.
  buttons.push([ { text: "🤖 Generate AI Summary", callback_data: "AI_SUMMARY" } ]);
}

// C. Always Add Main Menu
buttons.push([ { text: "🏠 Return to Dashboard", callback_data: "menu2" } ]);

// 5. Output structure
return {
  json: {
    ...$input.item.json,
    upsell_markup: { inline_keyboard: buttons },
    missing_count: missingOptions.length
  }
};

