  // 1. Create the base message object
  const body = {
    chat_id: $('TA Engine Trigger').item.json['telegram id'],
    text: $json.text_html,
    parse_mode: "HTML"
  };

  // 2. Only add buttons if there are NO charts
  if (!$json.has_charts) {
    body.reply_markup = $json.upsell_markup;
  }

  // 3. Return as String
  return JSON.stringify(body);
})() }}

